@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class FileAlterationObserver_ESTest_test15 extends FileAlterationObserver_ESTest_scaffolding {

    /**
     * Verifies that checkAndNotify() can be invoked repeatedly without error,
     * both before and after the observed directory comes into existence on the
     * virtual file system. The root directory does not exist for the first call;
     * a folder is then created on the VFS before the second call.
     */
    @Test(timeout = 4000)
    public void checkAndNotifyToleratesDirectoryAppearingOnFileSystem() throws Throwable {
        // Observe a directory referenced by an empty path on the virtual file system.
        MockFile observedDirectory = new MockFile("", "");
        FileAlterationObserver observer = new FileAlterationObserver(observedDirectory);

        // First check: the directory does not exist yet, so nothing is fired.
        observer.checkAndNotify();

        // Make a folder appear on the virtual file system.
        EvoSuiteFile createdFolder = new EvoSuiteFile("/Users/tenghaha/Desktop");
        FileSystemHandling.createFolder(createdFolder);

        // Second check: still completes without error.
        observer.checkAndNotify();
    }
}
